namespace sv_60710f43267d454880ad039c783cb2e6.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="sidebar-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

<div class="settings-section">
    <h3>Profile Settings</h3>

    @if (Profile is not null)
    {
        <div class="mb-4">
            <div class="avatar-preview mb-3">
                @if (!string.IsNullOrEmpty(EditDisplayName))
                {
                    <img src="@EditAvatarUrl" alt="Avatar" class="rounded-circle" style="width:80px;height:80px;object-fit:cover;" />
                }
                <div class="mt-2 text-muted small">@EditAvatarUrl</div>
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="EditDisplayName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="EditEmail" />
        </div>

        <div class="mb-3">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" @bind="EditAvatarUrl" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert @StatusCss mt-3" role="alert">@StatusMessage</div>
        }
    }
    else
    {
        <p>Loading profile...</p>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string EditDisplayName = "";
    private string EditEmail = "";
    private string EditAvatarUrl = "";
    private string EditBio = "";
    private string? StatusMessage;
    private string StatusCss = "alert-success";

    protected override void OnParametersSet()
    {
        if (Profile is not null && string.IsNullOrEmpty(EditDisplayName) && string.IsNullOrEmpty(StatusMessage))
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (Profile is null) return;
        EditDisplayName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditAvatarUrl = Profile.AvatarUrl;
        EditBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(EditDisplayName, EditEmail, EditAvatarUrl, EditBio);
        await OnSave.InvokeAsync(updated);
        StatusMessage = "Profile saved successfully!";
        StatusCss = "alert-success";
    }

    private void Discard()
    {
        ResetFields();
        StatusMessage = "Changes discarded.";
        StatusCss = "alert-info";
    }
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

<div class="settings-section">
    <h3>Notification Preferences</h3>

    @if (Prefs is not null)
    {
        <div class="mb-4">
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <h5>Muted Channels</h5>
        <div class="mb-4">
            @foreach (var channel in AvailableChannels)
            {
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@MutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert alert-success mt-3" role="alert">@StatusMessage</div>
        }
    }
    else
    {
        <p>Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = new() { "General", "Updates", "Marketing", "Alerts", "Support" };

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = new();
    private string? StatusMessage;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!isMuted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        StatusMessage = "Notification preferences saved!";
    }
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor:pointer" @onclick="() => IsExpanded = !IsExpanded">
        <span>Change Password</span>
        <span>@(IsExpanded ? "▲" : "▼")</span>
    </div>
    @if (IsExpanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="CurrentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="NewPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="ConfirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="alert alert-danger" role="alert">@ErrorMessage</div>
            }
            @if (!string.IsNullOrEmpty(SuccessMessage))
            {
                <div class="alert alert-success" role="alert">@SuccessMessage</div>
            }

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? ErrorMessage;
    private string? SuccessMessage;

    private async Task UpdatePasswordAsync()
    {
        ErrorMessage = null;
        SuccessMessage = null;

        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All password fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        SuccessMessage = "Password updated successfully!";
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

@if (Session is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@Session.Device</strong> from <strong>@Session.Location</strong>?</p>
                    <p class="text-muted small">Last active: @Session.LastActive.ToString("g")</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback<string> OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm()
    {
        if (Session is not null)
            await OnConfirm.InvokeAsync(Session.Id);
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (Settings is not null)
    {
        <ChangePasswordPanel OnChangePassword="HandlePasswordChange" />

        <div class="card mb-4">
            <div class="card-body">
                <div class="d-flex align-items-center justify-content-between">
                    <div>
                        <h5 class="mb-1">Two-Factor Authentication</h5>
                        <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" checked="@Settings.TwoFactorEnabled" disabled />
                    </div>
                </div>
                @if (Settings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">Last password change: @Settings.LastPasswordChange.Value.ToString("g")</p>
                }
            </div>
        </div>

        <h5>Active Sessions</h5>
        <div class="table-responsive">
            <table class="table table-striped">
                <thead>
