@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

@if (Session is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@Session.Device</strong> from <strong>@Session.Location</strong>?</p>
                    <p class="text-muted small">Last active: @Session.LastActive.ToString("g")</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback<string> OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm()
    {
        if (Session is not null)
            await OnConfirm.InvokeAsync(Session.Id);
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (Settings is not null)
    {
        <ChangePasswordPanel OnChangePassword="HandlePasswordChange" />

        <div class="card mb-4">
            <div class="card-body">
                <div class="d-flex align-items-center justify-content-between">
                    <div>
                        <h5 class="mb-1">Two-Factor Authentication</h5>
                        <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" checked="@Settings.TwoFactorEnabled" disabled />
                    </div>
                </div>
                @if (Settings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">Last password change: @Settings.LastPasswordChange.Value.ToString("g")</p>
                }
            </div>
        </div>

        <h5>Active Sessions</h5>
        <div class="table-responsive">
            <table class="table table-striped">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => SessionToRevoke = session">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-info">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <SessionRevokeDialog Session="@SessionToRevoke"
                             OnConfirm="HandleRevokeConfirmed"
                             OnCancel="() => SessionToRevoke = null" />
    }
    else
    {
        <p>Loading security settings...</p>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? SessionToRevoke;

    private async Task HandlePasswordChange((string Current, string New) passwords)
    {
        await OnChangePassword.InvokeAsync(passwords);
    }

    private async Task HandleRevokeConfirmed(string sessionId)
    {
        SessionToRevoke = null;
        await OnRevokeSession.InvokeAsync(sessionId);
    }
}

@namespace sv_60710f43267d454880ad039c783cb2e6.Components.Pages.Settings
@using sv_60710f43267d454880ad039c783cb2e6.Services

<div class="settings-section">
    <h3>Appearance Settings</h3>

    @if (Settings is not null)
    {
        <div class="mb-4">
            <h5>Theme</h5>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                           value="@theme" checked="@(SelectedTheme == theme)"
                           @onchange="() => SelectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h5>Font Size</h5>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                           value="@size" checked="@(SelectedFontSize == size)"
                           @onchange="() => SelectedFontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h5>Language</h5>
            <select class="form-select" style="max-width:250px" @bind="SelectedLanguage">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <div class="mb-4">
            <h5>Preview</h5>
            <div class="border rounded p-3 @PreviewClasses" style="@PreviewStyles">
                <h6>Sample Heading</h6>
                <p class="mb-1">This is a preview of your selected appearance settings.</p>
                <button class="btn btn-sm btn-primary">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert alert-success mt-3" role="alert">@StatusMessage</div>
        }
    }
    else
    {
        <p>Loading appearance settings...</p>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "en";
    private bool CompactMode;
    private string? StatusMessage;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            initialized = true;
        }
    }

    private string PreviewClasses => SelectedTheme == "Dark" ? "bg-dark text-light" : "bg-light text-dark";

    private string PreviewStyles
    {
        get
        {
            var fontSize = SelectedFontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.2rem",
                _ => "1rem"
            };
            var padding = CompactMode ? "0.5rem" : "1rem";
            return $"font-size:{fontSize};padding:{padding};";
        }
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        StatusMessage = "Appearance settings saved!";
    }
}

