using sv_60710f43267d454880ad039c783cb2e6.Services;

namespace sv_60710f43267d454880ad039c783cb2e6.Services;

public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new("Jane Doe", "jane@example.com", "https://i.pravatar.cc/150?img=5", "Software engineer and coffee enthusiast.");
    private NotificationPrefs _notifPrefs = new(true, true, false, new List<string> { "Marketing" });
    private SecuritySettings _security = new(true, DateTime.UtcNow.AddDays(-30), new List<ActiveSession>
    {
        new("current", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
        new("sess-2", "Safari on iPhone", "Boston, US", DateTime.UtcNow.AddHours(-2)),
        new("sess-3", "Firefox on Linux", "London, UK", DateTime.UtcNow.AddDays(-1))
    });
    private AppearanceSettings _appearance = new("Light", "Medium", "en", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
